-- 계산은 내가 한다

@Test
@Transactional
void 계산() {
    int page = 1, size = 5;
    List<Member> rows = memberJpaRepository.findByAge(10, page * size, size);
    long total = memberJpaRepository.totalCount(10);

    int totalPages = (int) Math.ceil((double) total / size);
    boolean hasNext = page + 1 < totalPages;
    boolean isLast  = page + 1 >= totalPages;
    boolean isFirst = page == 0;

    System.out.printf("페이지 %d/%d, 다음 %s, 마지막 %s, 처음 %s%n",
            page + 1, totalPages, hasNext, isLast, isFirst);
}

