-- 오프셋이 커지면

@Test
@Transactional
void 큰_오프셋() {
    em.createQuery("delete from Member").executeUpdate();
    for (int i = 0; i < 5000; i++) em.persist(new Member("p" + i, 10));
    em.flush(); em.clear();

    for (int offset : new int[]{0, 2000, 4900}) {
        em.clear();
        long t = System.nanoTime();
        em.createQuery("select m from Member m order by m.id", Member.class)
          .setFirstResult(offset).setMaxResults(20).getResultList();
        System.out.printf("offset %-6d %d ms%n",
                offset, (System.nanoTime() - t) / 1_000_000);
    }
}

