-- count 가 더 비쌀 수 있다

@Test
@Transactional
void count_비용() {
    em.clear();
    long t1 = System.nanoTime();
    em.createQuery("select m from Member m order by m.id", Member.class)
      .setFirstResult(0).setMaxResults(20).getResultList();
    long rows = (System.nanoTime() - t1) / 1_000_000;

    em.clear();
    long t2 = System.nanoTime();
    em.createQuery("select count(m) from Member m", Long.class)
      .getSingleResult();
    long cnt = (System.nanoTime() - t2) / 1_000_000;

    System.out.println("목록 20건: " + rows + " ms");
    System.out.println("전체 count: " + cnt + " ms");
}

