@Test
@Transactional
void 조인_count() {
    em.clear();
    long n = counter.count(() -> {
        em.createQuery("select m from Member m join m.team t" +
                       " where t.name like 'A%' order by m.id", Member.class)
          .setFirstResult(0).setMaxResults(20).getResultList();
        em.createQuery("select count(m) from Member m join m.team t" +
                       " where t.name like 'A%'", Long.class)
          .getSingleResult();
    });
    System.out.println("쿼리 " + n + "개");
}

